import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            A = next(iterator)
            B = next(iterator)
            N = int(next(iterator))

            patterns = []
            for _ in range(N):
                s_val = next(iterator)
                b_val = int(next(iterator))
                patterns.append((s_val, b_val))
        except StopIteration:
            break

        n_a = len(A)
        n_b = len(B)

        max_pleasure = 0

        for i in range(n_a + 1):
            for j in range(n_b + 1):
                C = A[:i] + B[:j]
                current_pleasure = 0

                for pat, beauty in patterns:
                    count = 0
                    start = 0
                    while True:
                        idx = C.find(pat, start)
                        if idx == -1:
                            break
                        count += 1
                        start = idx + 1
                    current_pleasure += count * beauty

                if current_pleasure > max_pleasure:
                    max_pleasure = current_pleasure

        print(max_pleasure)

if __name__ == "__main__":
    solve()
